// Sparse reversible edits. Imported audio and image payloads are immutable and shared.
const ROOT_KEYS=['nativeStory','sourceEngine','romObjects','name','activeMapId','links','authoring','story','terrainSets','prefabs','roomStyles','wallStyles','gateStyles','buildingTemplates','interiorTemplates','romEdits','regionMaps','travelEdits','tilesetAnimations','doorAnimations','cryEdits','hmRules','textEdits','developer','questFlags','questToken','spriteStudio','abilityStudio'];
const GRID_KEYS=['ground','details','objects','overhead','movement','wallCells'];
const copy=v=>v===undefined?undefined:structuredClone(v);
function nativeStoryCopy(story){if(!story)return story;return Object.fromEntries(Object.entries(story).map(([id,g])=>[id,{...g,edits:copy(g.edits)}]));}
function authorCopy(a){if(!a)return a;const {music=[],...rest}=a;return{...copy(rest),music:music.map(({asset,...t})=>({...copy(t),asset}))};}
function mapCopy(m){const {layers,movement,wallCells,rom,...rest}=m;return{fields:{...copy(rest),...(rom?{rom:{...copy(Object.fromEntries(Object.entries(rom).filter(([k])=>!['originalBlocks','sourceCells'].includes(k)))),originalBlocks:rom.originalBlocks,sourceCells:rom.sourceCells}}:{})},grids:{...Object.fromEntries(Object.entries(layers).map(([k,v])=>[k,v.slice()])),movement:movement?.slice(),wallCells:wallCells?.slice()}};}
export function equal(a,b){if(a===b)return true;if(!a||!b||typeof a!=='object'||typeof b!=='object')return false;const ak=Object.keys(a),bk=Object.keys(b);return ak.length===bk.length&&ak.every(k=>Object.hasOwn(b,k)&&equal(a[k],b[k]));}
export function captureEdit(project,mapId=null){const root={};for(const k of ROOT_KEYS){if(mapId&&['nativeStory','sourceEngine','authoring','story','romEdits','regionMaps','travelEdits','tilesetAnimations','doorAnimations','cryEdits','hmRules','textEdits','developer','questFlags','questToken','spriteStudio','abilityStudio','interiorTemplates'].includes(k))continue;root[k]=k==='nativeStory'?nativeStoryCopy(project[k]):k==='authoring'?authorCopy(project[k]):copy(project[k]);}return{mapId,root,assets:project.assets.map(a=>({...a,rom:copy(a.rom)})),maps:project.maps.filter(m=>!mapId||m.id===mapId).map(mapCopy),order:mapId?null:project.maps.map(m=>m.id)};}
function pairs(a,b){const out=[];for(const k of new Set([...Object.keys(a),...Object.keys(b)]))if(!equal(a[k],b[k]))out.push([k,a[k],b[k]]);return out;}
export function finishEdit(project,before){const after=captureEdit(project,before.mapId),maps=[],old=new Map(before.maps.map(m=>[m.fields.id,m])),now=new Map(after.maps.map(m=>[m.fields.id,m]));for(const id of new Set([...old.keys(),...now.keys()])){const a=old.get(id),b=now.get(id);if(!a||!b){maps.push({id,whole:[a,b]});continue;}const fields=pairs(a.fields,b.fields),grids=[];for(const k of GRID_KEYS){const x=a.grids[k],y=b.grids[k];if(!x||!y||x.length!==y.length){if(!equal(x,y))grids.push({key:k,whole:[x,y]});continue;}const cells=[];for(let i=0;i<x.length;i++)if(!equal(x[i],y[i]))cells.push([i,copy(x[i]),copy(y[i])]);if(cells.length)grids.push({key:k,cells});}if(fields.length||grids.length)maps.push({id,fields,grids});}const root=pairs(before.root,after.root),assets=equal(before.assets,after.assets)?null:[before.assets,after.assets],order=equal(before.order,after.order)?null:[before.order,after.order];if(!maps.length&&!root.length&&!assets&&!order)return null;return{maps,root,assets,order};}
function materialize(s){return{...copy(s.fields),layers:Object.fromEntries(['ground','details','objects','overhead'].map(k=>[k,(s.grids[k]||Array(s.fields.width*s.fields.height).fill(null)).slice()])),...(s.grids.movement?{movement:s.grids.movement.slice()}:{}),...(s.grids.wallCells?{wallCells:s.grids.wallCells.slice()}:{})};}
export function applyEdit(project,edit,forward=false){const side=forward?2:1,index=forward?1:0;for(const[k,a,b]of edit.root){const v=forward?b:a;if(v===undefined)delete project[k];else project[k]=k==='nativeStory'?nativeStoryCopy(v):k==='authoring'?authorCopy(v):copy(v);}if(edit.assets)project.assets=edit.assets[index].map(a=>({...a,rom:copy(a.rom)}));for(const delta of edit.maps){let m=project.maps.find(m=>m.id===delta.id);if(delta.whole){const s=delta.whole[index];project.maps=project.maps.filter(m=>m.id!==delta.id);if(s)project.maps.push(materialize(s));continue;}if(!m)throw Error('The undo map is missing.');for(const[k,a,b]of delta.fields){const v=forward?b:a;if(v===undefined)delete m[k];else m[k]=copy(v);}for(const g of delta.grids){const layer=['ground','details','objects','overhead'].includes(g.key),target=layer?m.layers:m;if(g.whole){const value=g.whole[index];if(value===undefined)delete target[g.key];else target[g.key]=value.slice();}else for(const cell of g.cells)target[g.key][cell[0]]=copy(cell[side]);}}if(edit.order){const order=edit.order[index];if(order)project.maps.sort((a,b)=>order.indexOf(a.id)-order.indexOf(b.id));}}
export function rollbackEdit(project,before){const edit=finishEdit(project,before);if(edit)applyEdit(project,edit);}
// Count retained data conservatively, without stringifying large payloads.
export function editBytes(edit){const seen=new WeakSet();for(const[k,a,b]of edit.root||[])if(k==='nativeStory')for(const id of Object.keys(a||{})){const x=a[id],y=b?.[id];if(x?.nodes===y?.nodes)for(const field of ['nodes','roots','texts','movements','mapKeys','notices'])if(x[field]&&typeof x[field]==='object')seen.add(x[field]);}function size(v){if(v==null)return 4;if(typeof v==='string')return v.length*2;if(typeof v!=='object')return 8;if(seen.has(v))return 0;seen.add(v);return 24+Object.entries(v).reduce((n,[k,x])=>n+k.length*2+size(x),0);}return size(edit);}

// Keep the newest edit reversible even when it alone exceeds the usual budget.
// Older edits are evicted first; the next edit can evict this large one normally.
export function trimEditHistory(history,maxBytes=12e6,maxEntries=35){
 let bytes=history.reduce((n,e)=>n+e.bytes,0);
 while(history.length>maxEntries||bytes>maxBytes&&history.length>1)bytes-=history.shift().bytes;
 return bytes;
}
